{"code":"def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    lines=[]
    # detect full-length horizontal/vertical monochrome lines
    for r in range(h):
        vals=set(grid[r])-{0}
        if len(vals)==1 and all(x!=0 for x in grid[r]): lines.append(('h',r,next(iter(vals))))
    for c in range(w):
        vals={grid[r][c] for r in range(h)}-{0}
        if len(vals)==1 and all(grid[r][c]!=0 for r in range(h)): lines.append(('v',c,next(iter(vals))))
    for typ,p,col in lines:
        if typ=='h': out[p]=grid[p][:]
        else:
            for r in range(h): out[r][p]=col
    linecolors={x[2] for x in lines}
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v==0 or v not in linecolors: continue
        # don't process line cells
        if any((t=='h' and r==p) or (t=='v' and c==p) for t,p,_ in lines): continue
        candidates=[]
        for t,p,k in lines:
          if k!=v: continue
          if t=='h': candidates.append((abs(r-p),t,p))
          else: candidates.append((abs(c-p),t,p))
        if not candidates: continue
        _,t,p=min(candidates)
        if t=='h':
          nr=p-1 if r<p else p+1
          if 0<=nr<h: out[nr][c]=v
        else:
          nc=p-1 if c<p else p+1
          if 0<=nc<w: out[r][nc]=v
    return out"}

