    h=len(grid); w=len(grid[0])
    out=[[0]*w for _ in range(h)]
    lines=[]
    # full nonzero horizontal/vertical stripes
    for r in range(h):
        if len(set(grid[r]))==1 and grid[r][0]!=0:
            lines.append(('h',r,grid[r][0]))
            out[r]=grid[r][:]
    for c in range(w):
        vals=[grid[r][c] for r in range(h)]
        if len(set(vals))==1 and vals[0]!=0:
            lines.append(('v',c,vals[0]))
            for r in range(h): out[r][c]=grid[r][c]
    bycolor={}
    for orient,pos,col in lines: bycolor.setdefault(col,[]).append((orient,pos))
    linecells=set()
    for orient,p,col in lines:
        if orient=='h':
            for c in range(w): linecells.add((p,c))
        else:
            for r in range(h): linecells.add((r,p))
    for r in range(h):
      for c in range(w):
        if (r,c) in linecells or grid[r][c]==0: continue
        col=grid[r][c]
        if col not in bycolor: continue
        # use matching line; normally unique
        orient,p=bycolor[col][0]
        if orient=='h':
            nr=p-1 if r<p else p+1
            if 0<=nr<h: out[nr][c]=col
        else:
            nc=p-1 if c<p else p+1
            if 0<=nc<w: out[r][nc]=col
    return out"}

